#!/usr/bin/env bash
# linkerd/linkerd-crds 1.8.0 - base variant: default
# Path: fetch this entry's retained objects, check their SHA-256, then apply
# them with kubectl. It uses curl, shasum, awk and kubectl. It needs no cub
# CLI and no ConfigHub account.
# Generated by scripts/generate-public-site.mjs from this entry's listing:
# https://confighub.github.io/helm-expt/site/listings/linkerd-linkerd-crds-1-8-0-default.json
# Entry page: https://confighub.github.io/helm-expt/site/charts/linkerd-linkerd-crds-1-8-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

for tool in curl awk kubectl; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    printf '%s is required and was not found.\n' "$tool" >&2
    exit 1
  fi
done
if command -v shasum >/dev/null 2>&1; then
  sha256_of() { shasum -a 256 "$1" | awk '{print $1}'; }
elif command -v sha256sum >/dev/null 2>&1; then
  sha256_of() { sha256sum "$1" | awk '{print $1}'; }
else
  printf 'shasum is required and was not found.\n' >&2
  exit 1
fi

work=./linkerd-linkerd-crds-1-8-0-default-objects
objects_url=https://raw.githubusercontent.com/confighub/helm-expt/main/recipes/linkerd/linkerd-crds/1.8.0/revisions/default/r001/rendered/release-objects.yaml
objects_sha256=af01ee9087a17f0ffabc7b8c0d6969a8fddde7dde977264ee92e6b12cd8ea01b

say "Fetch the retained objects into $work/objects.yaml"
mkdir -p "$work"
curl -fsSL -o "$work/objects.yaml" "$objects_url"

say "Check the file against the SHA-256 in the listing"
fetched_sha256="$(sha256_of "$work/objects.yaml")"
if [ "$fetched_sha256" != "$objects_sha256" ]; then
  printf 'The file differs from the listing, so the script stops. Nothing was applied.\n  listing: %s\n  fetched: %s\n' "$objects_sha256" "$fetched_sha256" >&2
  exit 1
fi
printf 'The file matches: sha256 %s\n' "$fetched_sha256"

say "Split the file into its 8 objects. The cluster is untouched so far"
rm -rf "$work/docs" "$work/crds"
mkdir -p "$work/docs" "$work/crds"
awk -v dir="$work/docs" 'BEGIN { n = 0; f = sprintf("%s/doc-%04d.yaml", dir, n) } /^---[ \t]*$/ { close(f); n++; f = sprintf("%s/doc-%04d.yaml", dir, n); next } { print > f }' "$work/objects.yaml"
for n in 0001 0002 0003 0004 0005 0006 0007 0008; do mv "$work/docs/doc-$n.yaml" "$work/crds/"; done
ls "$work/crds"

say "Check that kubectl reaches a cluster"
if ! kubectl get --raw /version >/dev/null 2>&1; then
  printf 'kubectl cannot reach a cluster. Point it at a throwaway cluster and re-run this script.\n' >&2
  exit 1
fi
kubectl config current-context 2>/dev/null || true

wait_for_crd() {
  crd_name="$1"
  deadline=$(( $(date +%s) + 180 ))
  until kubectl get "crd/${crd_name}" >/dev/null 2>&1; do
    if [ "$(date +%s)" -ge "$deadline" ]; then
      printf "CRD %s did not appear within 180 seconds.\n" "$crd_name" >&2
      return 1
    fi
    sleep 2
  done
  kubectl wait --for=condition=Established --timeout=120s "crd/${crd_name}"
}

say "Check the 8 CRDs this file holds"
missing_crds=0
if ! kubectl get crd/httproutes.gateway.networking.k8s.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/authorizationpolicies.policy.linkerd.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/httproutes.policy.linkerd.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/meshtlsauthentications.policy.linkerd.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/networkauthentications.policy.linkerd.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/serverauthorizations.policy.linkerd.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/servers.policy.linkerd.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/serviceprofiles.linkerd.io >/dev/null 2>&1; then
  missing_crds=1
fi
if [ "$missing_crds" -eq 1 ]; then
  say "A CRD is missing, so apply the file's CRDs first"
  kubectl apply --server-side -f "$work/crds"
  crd_outcome="were applied"
elif kubectl diff --server-side -f "$work/crds" >/dev/null 2>&1; then
  say "The CRDs already exist and match this file. The script leaves them under their current owner"
  crd_outcome="already existed and matched, so the script left them alone"
elif [ "${APPLY_CRDS:-0}" = "1" ]; then
  say "The existing CRDs differ from this file. APPLY_CRDS=1 is set, so the script applies the file's CRDs"
  kubectl apply --server-side -f "$work/crds"
  crd_outcome="differed and were applied, because APPLY_CRDS=1 was set"
else
  say "The CRDs already exist and differ from this file, or another tool owns them"
  cat <<'EOF_CRDS'
This script does not change CRDs it did not just create.
If this is an upgrade, the objects that follow may need the newer CRDs.
To let this script apply the file's CRDs, re-run with:
  APPLY_CRDS=1 bash try-objects.sh
EOF_CRDS
  exit 1
fi
wait_for_crd httproutes.gateway.networking.k8s.io
wait_for_crd authorizationpolicies.policy.linkerd.io
wait_for_crd httproutes.policy.linkerd.io
wait_for_crd meshtlsauthentications.policy.linkerd.io
wait_for_crd networkauthentications.policy.linkerd.io
wait_for_crd serverauthorizations.policy.linkerd.io
wait_for_crd servers.policy.linkerd.io
wait_for_crd serviceprofiles.linkerd.io

say "Done. The 8 CRDs of this entry's retained file $crd_outcome."
say "The script stops here. It did not wait for any workload to start"
